import init, { initSync, WasmNormalizer } from './fidel_tools_core_native.js';

const wasmBase64 = "";

let wasmBytes = null;
function getWasmBytes() {
  if (!wasmBytes) {
    if (typeof Buffer !== 'undefined') {
      wasmBytes = Buffer.from(wasmBase64, 'base64');
    } else {
      const binaryString = atob(wasmBase64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      wasmBytes = bytes;
    }
  }
  return wasmBytes;
}

let initialized = false;
export function initNormalizer() {
  if (!initialized) {
    initSync({ module: getWasmBytes() });
    initialized = true;
  }
}

export { WasmNormalizer };
